var makeGood = function(s) {
    const stack = [];
    for (const c of s) {
        const top = stack[stack.length - 1];
        // A bad pair: same letter but different case (e.g., 'a' and 'A')
        const isBadPair = stack.length > 0 &&
                          top !== c &&
                          top.toLowerCase() === c.toLowerCase();

        if (isBadPair) {
            stack.pop(); // cancel out the bad pair
        } else {
            stack.push(c);
        }
    }
    return stack.join('');
};
